<script setup>
import TripTracking from './modules/traceability/presentation/components/TripTracking.vue';
import AccountHelp from './modules/access/presentation/AccountHelp.vue';
import OrganizationWorkspace from './modules/access/presentation/OrganizationWorkspace.vue';
import DevicesWorkspace from './modules/devices/DevicesWorkspace.vue';
import ReportingWorkspace from './modules/reporting/ReportingWorkspace.vue';
import GeofenceOperations from './modules/traceability/presentation/components/GeofenceOperations.vue';
import ProcessingOperations from './modules/processing/ProcessingOperations.vue';
import JewelryWorkspace from './modules/jewelry/JewelryWorkspace.vue';
import CertificationWorkspace from './modules/certification/CertificationWorkspace.vue';
import PublicCertificate from './modules/certification/PublicCertificate.vue';
import { reactive, ref, watch } from 'vue';
import { useTraceabilityWorkspace } from './modules/traceability/presentation/composables/useTraceabilityWorkspace.js';
import RoleAdministration from './modules/access/presentation/RoleAdministration.vue';
import LotOperations from './modules/traceability/presentation/components/LotOperations.vue';
import ShipmentOperations from './modules/traceability/presentation/components/ShipmentOperations.vue';
import CaptureSyncStatus from './modules/traceability/presentation/components/CaptureSyncStatus.vue';
const {identity,captures,lot,error,notice,online,busy,qr,sessionVerified,login,logout,capture,synchronize,lookup,can,operations,custody,pendingAcceptance,cancelLot,prepareHandover,acceptCustody,refreshIdentity}=useTraceabilityWorkspace();
const publicId=window.location.pathname.match(/^\/verify\/([^/]+)\/?$/)?.[1],view=ref('lots');
const code=ref(''),mfa=ref(false);
const email=ref(''),password=ref(''),lookupId=ref('');
watch(()=>identity.value?.userId,()=>{view.value='lots';});
const form=reactive({mineralType:'Gold',weight:'',weightUnit:'kg',reference:'',source:'',latitude:'',longitude:'',concessionId:''});
async function submitLogin(){const result=await login(email.value,password.value,code.value||undefined);mfa.value=result==='MFA_REQUIRED';code.value='';if(!mfa.value)password.value='';}
async function submitCapture(){if(await capture({mineralType:form.mineralType,weight:form.weight,weightUnit:form.weightUnit,originEvidence:{reference:form.reference,source:form.source},...(form.latitude!==''||form.longitude!==''||form.concessionId?{location:form.latitude!==''&&form.longitude!==''?{latitude:Number(form.latitude),longitude:Number(form.longitude)}:null,concessionId:form.concessionId||null}:{})})){form.weight='';form.reference='';}}
</script>
<template>
<PublicCertificate v-if="publicId" :id="publicId" /><main v-else class="workspace">
<header class="topbar"><div><p class="eyebrow">XTRACTA · TRAZABILIDAD MINERAL</p><h1>EventOre</h1></div><span :class="['connection',online?'connected':'offline']">{{online?'Con conexión':'Sin conexión'}}</span></header>
<p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p>
<template v-if="!identity"><section class="panel login"><h2>Accede a tu organización</h2><p>Usa la cuenta provisionada por el administrador para registrar y consultar lotes.</p><form @submit.prevent="submitLogin"><label>Correo<input v-model="email" type="email" autocomplete="username" required /></label><label>Contraseña<input v-model="password" type="password" autocomplete="current-password" required maxlength="128" /></label><label v-if="mfa">Código de segundo factor<input v-model="code" autocomplete="one-time-code" inputmode="numeric" maxlength="6" /></label><button :disabled="busy||!online">{{busy?'Ingresando…':'Iniciar sesión'}}</button></form></section><AccountHelp /></template>
<template v-else>
<section class="account"><div><strong>{{identity.email}}</strong><p>Roles: {{identity.roles?.join(', ')}}</p><p>Organización {{identity.tenantId}}</p><small v-if="!sessionVerified">La sesión debe verificarse al recuperar conexión.</small></div><button class="secondary" @click="logout" :disabled="!online">Cerrar sesión</button></section>
<TripTracking :key="identity.tenantId+identity.userId" :identity="identity" :online="online" :lot="lot" />
<nav class="workspace-nav" aria-label="Módulos"><button :class="{secondary:view!=='lots'}" @click="view='lots'">Lotes y planta</button><button v-if="can('inventory.manage')" :class="{secondary:view!=='jewelry'}" @click="view='jewelry'">Joyería</button><button v-if="can('certificates.read')" :class="{secondary:view!=='certificates'}" @click="view='certificates'">Certificados</button><button :class="{secondary:view!=='devices'}" @click="view='devices'">Dispositivos</button><button v-if="can('reporting.read')" :class="{secondary:view!=='reports'}" @click="view='reports'">Reportes</button><button v-if="can('users.manage')||can('inventory.manage')" :class="{secondary:view!=='organization'}" @click="view='organization'">Organización</button></nav><OrganizationWorkspace v-if="view==='organization'" :manage-billing="can('users.manage')" :manage-keys="can('inventory.manage')" /><DevicesWorkspace v-if="view==='devices'" :identity="identity" :online="online" /><ReportingWorkspace v-if="view==='reports'&&can('reporting.read')" :identity="identity" :online="online" /><JewelryWorkspace v-if="view==='jewelry'&&can('inventory.manage')" :identity="identity" :online="online" /><CertificationWorkspace v-if="view==='certificates'&&can('certificates.read')" :identity="identity" :online="online" /><template v-if="view==='lots'"><RoleAdministration v-if="can('users.manage')" @changed="refreshIdentity" /><div class="columns"><section v-if="can('lots.register')" class="panel"><h2>Registrar lote</h2><p>La captura se conserva localmente antes de enviarse al servidor.</p><form @submit.prevent="submitCapture"><label>Mineral<input v-model="form.mineralType" required maxlength="100" /></label><div class="formrow"><label>Peso<input v-model="form.weight" type="text" inputmode="decimal" placeholder="125.50" required /></label><label>Unidad<select v-model="form.weightUnit"><option>g</option><option>kg</option><option>t</option></select></label></div><label>Referencia de evidencia<input v-model="form.reference" required maxlength="500" /></label><label>Fuente declarada<input v-model="form.source" required maxlength="500" /></label><details><summary>Ubicación declarada opcional</summary><div class="formrow"><label>Latitud de captura<input v-model="form.latitude" type="number" step="any" min="-90" max="90" /></label><label>Longitud de captura<input v-model="form.longitude" type="number" step="any" min="-180" max="180" /></label></div><label>ID de concesión declarada<input v-model="form.concessionId" /></label><p class="muted">Se conserva como pendiente de comprobación, incluso sin conexión.</p></details><button :disabled="busy">{{busy?'Guardando…':'Guardar captura'}}</button></form><p class="muted">La evidencia queda pendiente de revisión. Registrar un lote no verifica su procedencia.</p></section>
<section class="panel"><h2>Consultar lote</h2><form @submit.prevent="lookup(lookupId)"><label>Identificador del lote<input v-model="lookupId" placeholder="UUID del lote" required /></label><button :disabled="!online">Consultar</button></form><div v-if="lot" class="lot"><h3>{{lot.mineralType}} · {{lot.weight}} {{lot.weightUnit}}</h3><p class="identifier">{{lot.lotId}}</p><dl><dt>Estado</dt><dd>{{lot.status}}</dd><dt>Evidencia</dt><dd>{{lot.originEvidenceStatus}}</dd><dt>Versión</dt><dd>{{lot.version}}</dd></dl><p v-if="lot.status==='Cancelled'" class="alert error">Lote cancelado. No habilitado para transporte.</p><img v-if="qr" :src="qr" alt="Código QR para consultar este lote" width="180" height="180" /><p class="muted">El QR identifica el registro; no certifica autenticidad ni origen ético.</p>
<LotOperations :lot="lot" :identity="identity" :operations="operations" :custody="custody" :pending-acceptance="pendingAcceptance" :busy="busy" :online="online"
 @cancel="cancelLot" @prepare="prepareHandover" @accept="acceptCustody" @refresh="lookup(lot.lotId)" />
<ShipmentOperations :lot="lot" :identity="identity" :online="online" @refresh="lookup(lot.lotId)" /><GeofenceOperations :lot="lot" :identity="identity" :online="online" @refresh="lookup(lot.lotId)" /><ProcessingOperations :lot="lot" :identity="identity" :online="online" @refresh="lookup(lot.lotId)" /></div></section></div>
<section class="panel"><div class="sectionhead"><h2>Capturas de este dispositivo</h2><button class="secondary" @click="synchronize" :disabled="!online||busy||!can('lots.register')">Sincronizar pendientes</button></div><p v-if="!captures.length">Todavía no hay capturas para esta organización.</p><ul class="captures"><li v-for="item in captures" :key="item.clientEventId"><div><strong>{{item.payload.mineralType}} · {{item.payload.weight}} {{item.payload.weightUnit}}</strong><p class="identifier">{{item.clientEventId}}</p><CaptureSyncStatus :status="item.status" :reason="item.reason??''" /></div><button v-if="item.lotId" class="secondary" @click="lookup(item.lotId)" :disabled="!online">Ver lote</button></li></ul></section>
</template></template></main>
</template>
